using System;
using System.Net;
using System.Net.Sockets;

public class SocketEndpointValidator
{
    public static bool IsValidSocketEndpoint(string? endpointStr)
    {
        if (string.IsNullOrWhiteSpace(endpointStr)) return false;

        string[] parts = endpointStr.Trim().Split(':');
        if (parts.Length != 2) return false;

        // Validasi IP
        if (!IPAddress.TryParse(parts[0], out var ip)) return false;
        if (ip.AddressFamily != AddressFamily.InterNetwork) return false;

        // Validasi Port
        if (!int.TryParse(parts[1], out int port)) return false;
        if (port < 1 || port > 65535) return false;

        return true;
    }

    public static void Main()
    {
        Console.WriteLine(IsValidSocketEndpoint("127.0.0.1:5000"));
        Console.WriteLine(IsValidSocketEndpoint("999.1.1.1:80"));
        Console.WriteLine(IsValidSocketEndpoint("10.0.0.1:99999"));
    }
}
